-- Canonical acquisition timestamps, including fractional seconds and UTC offsets.
-- Separate integer seconds/nanoseconds avoid float precision loss and epoch overflow.
CREATE INDEX work_contracts_workspace_acquired ON work_contracts(namespace_id,outcome_id,work_item_id,(CAST(strftime('%s',substr(json_extract(state_json,'$.acquired_at'),1,19)||(CASE WHEN substr(json_extract(state_json,'$.acquired_at'),-1)='Z' THEN 'Z' ELSE substr(json_extract(state_json,'$.acquired_at'),-6) END)) AS INTEGER)) DESC,(CASE WHEN substr(json_extract(state_json,'$.acquired_at'),20,1)='.' THEN CAST(substr(substr(json_extract(state_json,'$.acquired_at'),21,length(json_extract(state_json,'$.acquired_at'))-20-(CASE WHEN substr(json_extract(state_json,'$.acquired_at'),-1)='Z' THEN 1 ELSE 6 END))||'000000000',1,9) AS INTEGER) ELSE 0 END) DESC,id DESC);
CREATE INDEX signed_work_contracts_workspace_acquired ON signed_work_contracts(namespace_id,outcome_id,work_item_id,(CAST(strftime('%s',substr(json_extract(state_json,'$.acquired_at'),1,19)||(CASE WHEN substr(json_extract(state_json,'$.acquired_at'),-1)='Z' THEN 'Z' ELSE substr(json_extract(state_json,'$.acquired_at'),-6) END)) AS INTEGER)) DESC,(CASE WHEN substr(json_extract(state_json,'$.acquired_at'),20,1)='.' THEN CAST(substr(substr(json_extract(state_json,'$.acquired_at'),21,length(json_extract(state_json,'$.acquired_at'))-20-(CASE WHEN substr(json_extract(state_json,'$.acquired_at'),-1)='Z' THEN 1 ELSE 6 END))||'000000000',1,9) AS INTEGER) ELSE 0 END) DESC,id DESC);
